-- ============ ROW LEVEL SECURITY ============
CREATE OR REPLACE FUNCTION public.is_admin() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (SELECT 1 FROM public.admin_users WHERE email = lower(coalesce(auth.jwt() ->> 'email', '')));
$$;

ALTER TABLE public.profile ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "public read" ON public.profile;
CREATE POLICY "public read" ON public.profile FOR SELECT TO anon, authenticated USING (true);
DROP POLICY IF EXISTS "admin write" ON public.profile;
CREATE POLICY "admin write" ON public.profile FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin());

